/** @type {Food[]} */
export const FOODS = RAW.map(([k, n, g, p, t, a, c, sr, vals, gr]) => {
  /** @type {Partial<Record<NutrientKey, number>>} */
  const v = {};
  vals.forEach((x, i) => {
    if (x !== null) v[COLS[i]] = x;
  });
  return { k, n, g, p, t, ...(a.length ? { a } : {}), c: c === 1, sr, v, gr };
});
